9	 it('enforces single mode under lock but allows distinct sessions in multi mode',async()=>{const first=entry();writeTimeTrackerEntries([first]);const next=entry();await expect(commitTimeTrackerEntries([first,next],[first],accountScope.capture())).rejects.toThrow('Single-task');localStorage.setItem('xai_tt_mode','multi');await commitTimeTrackerEntries([first,next],[first],accountScope.capture());expect(readTimeTrackerEntries()).toHaveLength(2)});
10	 it('retains malformed original bytes and refuses implicit repair',async()=>{const bad={...entry(),segments:[{start:1000,end:null},{start:2000,end:null}]};const bytes=' '+JSON.stringify([bad])+' ';localStorage.setItem(accountScope.physicalKey(TIME_TRACKER_ENTRIES_KEY),bytes);await expect(commitTimeTrackerEntries([],readTimeTrackerEntries(),accountScope.capture())).rejects.toThrow('recovery');expect(raw()).toBe(bytes)});
